import os, tarfile, json

archive_path = '/home/azureuser/FULL_HOME_BACKUP/azure_home_FULL_filesystem_20260925.tar.gz'

print('Step 1: Reading tar archive members...')
tar_members = {}
tar_hardlinks = {}
tar_symlinks = {}
tar_dirs = {}
tar_regular_bytes = 0
tar_hardlink_bytes = 0

with tarfile.open(archive_path, 'r:gz') as tar:
    for m in tar:
        # Standardize name: 'home/...' -> '/home/...'
        p = '/' + m.name.rstrip('/')
        if m.isfile():
            tar_members[p] = m.size
            tar_regular_bytes += m.size
        elif m.islnk():
            tar_hardlinks[p] = (m.linkname, m.size)
            # Find the size of the target
            target_p = '/' + m.linkname.rstrip('/')
            tar_hardlink_bytes += tar_members.get(target_p, 0)
        elif m.issym():
            tar_symlinks[p] = m.linkname
        elif m.isdir():
            tar_dirs[p] = True

print(f'Archive Regular Files:    {len(tar_members):,}')
print(f'Archive Hard Links:       {len(tar_hardlinks):,}')
print(f'Archive Symlinks:         {len(tar_symlinks):,}')
print(f'Archive Directories:      {len(tar_dirs):,}')
print(f'Archive Stored Reg Bytes: {tar_regular_bytes:,} bytes')
print(f'Archive Deduped HL Bytes: {tar_hardlink_bytes:,} bytes')
print(f'Archive Total Logical B:  {tar_regular_bytes + tar_hardlink_bytes:,} bytes')

print('\nStep 2: Scanning filesystem source...')
src_files = {}
src_symlinks = {}
src_dirs = {}
src_special = {}
src_inodes = {}
src_hardlinks_count = 0
src_total_bytes = 0

for root, dirs, files in os.walk('/home'):
    # Exclude backup output and tmp
    if root.startswith('/home/azureuser/FULL_HOME_BACKUP') or root.startswith('/home/azureuser/tmp'):
        continue
    for d in dirs:
        dp = os.path.join(root, d)
        src_dirs[dp] = True
    for f in files:
        fp = os.path.join(root, f)
        try:
            st = os.lstat(fp)
        except OSError as e:
            src_special[fp] = str(e)
            continue

        if os.path.islink(fp):
            src_symlinks[fp] = os.readlink(fp)
        elif os.path.isfile(fp):
            src_files[fp] = st.st_size
            src_total_bytes += st.st_size
            if st.st_nlink > 1:
                src_hardlinks_count += 1
                if st.st_ino not in src_inodes:
                    src_inodes[st.st_ino] = []
                src_inodes[st.st_ino].append(fp)
        else:
            src_special[fp] = f'mode_{st.st_mode}'

print(f'Source Regular Files:     {len(src_files):,}')
print(f'Source Symlinks:          {len(src_symlinks):,}')
print(f'Source Directories:       {len(src_dirs):,}')
print(f'Source Special (sockets): {len(src_special):,}')
print(f'Source Files with nlink>1:{src_hardlinks_count:,}')
print(f'Unique Inodes with nlink>1:{len(src_inodes):,}')
print(f'Source Total File Bytes:  {src_total_bytes:,} bytes')

# Calculate missing files
missing_from_tar = set(src_files.keys()) - (set(tar_members.keys()) | set(tar_hardlinks.keys()))
print(f'\nStep 3: Comparing Source vs Archive...')
print(f'Files in Source missing from Archive: {len(missing_from_tar)}')
missing_bytes = 0
for mf in missing_from_tar:
    sz = src_files[mf]
    missing_bytes += sz
    print(f'  MISSING: {mf} ({sz:,} bytes)')

archive_extra = (set(tar_members.keys()) | set(tar_hardlinks.keys())) - set(src_files.keys())
print(f'Files in Archive not in Source: {len(archive_extra)}')
